entries":4,"stock_status":"Tagged items","source_reference":"IMG_2741(1).jpeg","source_row":8,"derived_parent":false},{"platform":"F22","bin_code":"F22-005","parent_bin_code":"F22-005","description":"STARTING & CHARGING","tagged_entries":4,"stock_status":"Tagged items","source_reference":"IMG_2727(1).jpeg","source_row":9,"derived_parent":false},{"platform":"F22","bin_code":"F22-006","parent_bin_code":"F22-006","description":"STARTING & CHARGING","tagged_entries":3,"stock_status":"Tagged items","source_reference":"IMG_2727(1).jpeg","source_row":10,"derived_parent":false},{"platform":"F22","bin_code":"F22-007","parent_bin_code":"F22-007","description":"ENGINE / TRANS / SENSORS","tagged_entries":3,"stock_status":"Tagged items","source_reference":"IMG_2728(1).jpeg","source_row":11,"derived_parent":false},{"platform":"F22","bin_code":"F22-008","parent_bin_code":"F22-008","description":"WHEEL STUDS & LUG NUTS","tagged_entries":8,"stock_status":"Parent bin / sub-bins listed","source_reference":"Parent relationship in workbook","source_row":null,"derived_parent":true},{"platform":"F22","bin_code":"F22-008-A","parent_bin_code":"F22-008","description":"WHEEL STUDS & LUG NUTS · FRONT","tagged_entries":3,"stock_status":"Tagged items","source_reference":"IMG_2729(1).jpeg","source_row":12,"derived_parent":false},{"platform":"F22","bin_code":"F22-008-B","parent_bin_code":"F22-008","description":"WHEEL STUDS & LUG NUTS · REAR","tagged_entries":3,"stock_status":"Tagged items","source_reference":"IMG_2729(1).jpeg","source_row":13,"derived_parent":false},{"platform":"F22","bin_code":"F22-008-C","parent_bin_code":"F22-008","description":"WHEEL STUDS & LUG NUTS · LUG NUTS","tagged_entries":2,"stock_status":"Tagged items","source_reference":"IMG_2729(1).jpeg","source_row":14,"derived_parent":false},{"platform":"F22","bin_code":"F22-009","parent_bin_code":"F22-009","description":"MISC ENGINE CONNECTORS","tagged_entries":0,"stock_status":"Uncounted / bin note","source_reference":"Inventory photos / batch 01–02","source_row":15,"derived_parent":false},{"platform":"F22","bin_code":"F22-010","parent_bin_code":"F22-010","description":"IGNITION","tagged_entries":4,"stock_status":"Tagged items","source_reference":"IMG_2731(1).jpeg","source_row":16,"derived_parent":false},{"platform":"F22","bin_code":"F22-011","parent_bin_code":"F22-011","description":"ENGINE GASKET / O-RINGS","tagged_entries":0,"stock_status":"Uncounted / bin note","source_reference":"Inventory photos / batch 01–02","source_row":17,"derived_parent":false},{"platform":"F22","bin_code":"F22-012","parent_bin_code":"F22-012","description":"FUEL SYSTEM / OIL SYSTEM","tagged_entries":17,"stock_status":"Tagged items","source_reference":"IMG_2733(1).jpeg","source_row":18,"derived_parent":false},{"platform":"F22","bin_code":"F22-014","parent_bin_code":"F22-014","description":"ELECTRICAL MODULES","tagged_entries":6,"stock_status":"Tagged items","source_reference":"IMG_2734(1).jpeg","source_row":19,"derived_parent":false},{"platform":"F22","bin_code":"F22-015","parent_bin_code":"F22-015","description":"HARDWARE (NON-BODY)","tagged_entries":5,"stock_status":"Parent bin / sub-bins listed","source_reference":"Parent relationship in workbook","source_row":null,"derived_parent":true},{"platform":"F22","bin_code":"F22-015-A","parent_bin_code":"F22-015","description":"HARDWARE (NON-BODY) · MISC LOOSE","tagged_entries":5,"stock_status":"Tagged items","source_reference":"IMG_2735(1).jpeg","source_row":20,"derived_parent":false},{"platform":"F22","bin_code":"F22-016","parent_bin_code":"F22-016","description":"HARDWARE (SUSPENSION)","tagged_entries":11,"stock_status":"Tagged items","source_reference":"IMG_2736(1).jpeg","source_row":21,"derived_parent":false},{"platform":"F22","bin_code":"F22-017","parent_bin_code":"F22-017","description":"COOLING GENERAL","tagged_entries":5,"stock_status":"Tagged items","source_reference":"IMG_2737(1).jpeg","source_row":22,"derived_parent":false},{"platform":"F22","bin_code":"F22-018","parent_bin_code":"F22-018","description":"SERVICE KIT · TOTE","tagged_entries":0,"stock_status":"Uncounted / bin note","source_reference":"Inventory photos / batch 01–02","source_row":23,"derived_parent":false},{"platform":"F22","bin_code":"F22-019","parent_bin_code":"F22-019","description":"SERPENTINE SYSTEM · TOTE","tagged_entries":6,"stock_status":"Tagged items","source_reference":"IMG_2739(1).jpeg","source_row":24,"derived_parent":false},{"platform":"F22","bin_code":"F22-020","parent_bin_code":"F22-020","description":"ENGINE MOUNTS · 2q TOTE","tagged_entries":3,"stock_status":"Tagged items","source_reference":"IMG_2740(1).jpeg","source_row":25,"derived_parent":false}]'::jsonb;
  v_snapshot_id text := 'f22-e92-2026-11-08';
  v_source_sha256 text := '16f228c5e67a0da7ed6e6eef4a6cff94143dd914a7b3c1d6dc7ab8adcca6cb0a';
  v_other_inventory_before jsonb;
  v_other_inventory_after jsonb;
  v_registry_before jsonb;
  v_registry_after jsonb;
  v_count integer;
begin
  if exists(select 1 from otr_inventory_archive.replacement_batches where snapshot_id=v_snapshot_id) then
    if exists(select 1 from otr_inventory_archive.replacement_batches where snapshot_id=v_snapshot_id and source_sha256<>v_source_sha256) then
      raise exception 'Snapshot ID already exists with a different workbook hash';
    end if;
    raise notice 'Snapshot % already applied; no inventory changed',v_snapshot_id;
    return;
  end if;

  -- Abort if a workbook Bin ID is already owned by a different chassis.
  if exists(
    select 1 from public.inventory_bins b
    join jsonb_array_elements(v_bins) incoming on b.bin_code=incoming->>'bin_code'
    where b.model is distinct from incoming->>'platform'
  ) then
    raise exception 'Workbook Bin ID conflicts with an existing bin chassis';
  end if;

  select coalesce(jsonb_agg(to_jsonb(i) order by i.id),'[]'::jsonb)
    into v_other_inventory_before from public.inventory_items i
    where i.platform is null or i.platform not in ('F22','E92','M235 / M235iR');
  select coalesce(jsonb_agg(to_jsonb(v) order by v.vehicle_code),'[]'::jsonb)
    into v_registry_before from public.vehicles v;

  insert into otr_inventory_archive.replacement_batches(snapshot_id,source_sha256,source_snapshot)
    values(v_snapshot_id,v_source_sha256,v_source);
  insert into otr_inventory_archive.inventory_items(snapshot_id,inventory_item_id,original_row)
    select v_snapshot_id,id,to_jsonb(i) from public.inventory_items i
    where platform in ('F22','E92','M235 / M235iR');
  insert into otr_inventory_archive.inventory_bins(snapshot_id,inventory_bin_id,original_row)
    select v_snapshot_id,b.id,to_jsonb(b) from public.inventory_bins b
    where b.bin_code in(select incoming->>'bin_code' from jsonb_array_elements(v_bins) incoming);

  delete from public.inventory_items where platform in ('F22','E92','M235 / M235iR');

  insert into public.inventory_bins(
    bin_code,make,make_prefix,model,system,description,label_format,qr_value,status,source_metadata
  )
    select incoming->>'bin_code','BMW','B',incoming->>'platform',incoming->>'description',
      incoming->>'description','4x6','OTR:BIN:'||(incoming->>'bin_code'),'Active',
      incoming || jsonb_build_object('snapshot_id',v_snapshot_id,'source_file',v_source->>'source_file')
    from jsonb_array_elements(v_bins) incoming
    on conflict(bin_code) do update set
      make=excluded.make,make_prefix=excluded.make_prefix,model=excluded.model,
      system=excluded.system,description=excluded.description,label_format=excluded.label_format,
      qr_value=excluded.qr_value,status=excluded.status,source_metadata=excluded.source_metadata;

  update public.inventory_bins child set parent_bin_id=parent.id
    from jsonb_array_elements(v_bins) incoming,public.inventory_bins parent
    where child.bin_code=incoming->>'bin_code'
      and parent.bin_code=incoming->>'parent_bin_code'
      and child.id<>parent.id;

  insert into public.inventory_items(
    inventory_code,platform,location,category,item_name,quantity,condition,status,notes,source,
    verification_status,original_quantity,original_item_text,original_location,part_number,
    compatibility,assignment_type,inventory_bin_id,quantity_unit,source_metadata
  )
    select incoming->>'inventory_code',incoming->>'platform',incoming->>'bin_code',incoming->>'category',
      incoming->>'item_name',(incoming->>'quantity')::integer,incoming->>'condition',
      case when incoming->>'quantity' is null then 'Uncounted'
           when (incoming->>'quantity')::integer=0 then 'Out of Stock' else 'In Stock' end,
      incoming->>'label_note',v_source->>'source_file',
      case when (incoming->>'quantity')::integer=0 then 'Consumed/Removed' else 'Imported' end,
      (incoming->>'quantity')::integer,incoming->>'label_text',incoming->>'bin_code',incoming->>'part_number',
      incoming->'compatibility','General Inventory',b.id,incoming->>'quantity_unit',
      incoming || jsonb_build_object('snapshot_id',v_snapshot_id,'source_file',v_source->>'source_file')
    from jsonb_array_elements(v_source->'parts') incoming
    join public.inventory_bins b on b.bin_code=incoming->>'bin_code';

  get diagnostics v_count = row_count;
  if v_count<>215 then raise exception 'Expected 215 source labels, inserted %',v_count; end if;
  if (select count(*) from public.inventory_items where platform='F22')<>92 or
     (select count(*) from public.inventory_items where platform='E92')<>123 or
     (select count(*) from public.inventory_items where platform in ('F22','E92') and quantity is null)<>5 then
    raise exception 'Workbook chassis or unknown-count totals do not match';
  end if;

  select coalesce(jsonb_agg(to_jsonb(i) order by i.id),'[]'::jsonb)
    into v_other_inventory_after from public.inventory_items i
    where i.platform is null or i.platform not in ('F22','E92','M235 / M235iR');
  select coalesce(jsonb_agg(to_jsonb(v) order by v.vehicle_code),'[]'::jsonb)
    into v_registry_after from public.vehicles v;
  if v_other_inventory_before<>v_other_inventory_after or v_registry_before<>v_registry_after then
    raise exception 'Unrelated inventory or vehicle registry changed; replacement rolled back';
  end if;
end;
$inventory_update$;

commit;
